package io.github.rebrowser.data;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.ComponentGate;
import io.github.rebrowser.download.DownloadStore;
import io.github.rebrowser.crypto.PrivateRecordSealer;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
/** Actual HOST JCA/filesystem/fixed p6/CAS; private synthetic key/source/path only, NOT Android. */
public final class DownloadMetadataStoreTest {
 static final class NativeTask implements AutoCloseable {
  final io.github.rebrowser.core.TaskCoordinator coordinator;final io.github.rebrowser.core.TaskCoordinator.Submission task;
  NativeTask(ComponentGate gate)throws Exception{Class<?> backend=Class.forName("io.github.rebrowser.core.TaskCoordinator$JournalBackend");Object journal=java.lang.reflect.Proxy.newProxyInstance(backend.getClassLoader(),new Class<?>[]{backend},(p,m,a)->{((io.github.rebrowser.core.TaskCoordinator.CommitFence)a[a.length-1]).checkCurrent();((io.github.rebrowser.core.TaskCoordinator.CommitFence)a[a.length-1]).checkCurrent();return m.getName().equals("start")?new Object():null;});java.lang.reflect.Constructor<io.github.rebrowser.core.TaskCoordinator> ctor=io.github.rebrowser.core.TaskCoordinator.class.getDeclaredConstructor(ComponentGate.class,backend,io.github.rebrowser.core.TaskCoordinator.CurrentContext.class,int.class);ctor.setAccessible(true);coordinator=ctor.newInstance(gate,journal,(io.github.rebrowser.core.TaskCoordinator.CurrentContext)j->{},1);java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(1);task=coordinator.submitNativeReserved("j_00000000000000000000000000000001",io.github.rebrowser.core.TaskCoordinator.Lane.READ,gate.requireBusiness(),owner->{owner.commitBeforeExternalDispatch();ready.countDown();});assertTrue(ready.await(3,java.util.concurrent.TimeUnit.SECONDS));}
  public void close()throws Exception{task.nativeOwner().reportActualDomainChainEnd(io.github.rebrowser.core.Cancellation.EndReason.UNDERLYING_RETURNED);coordinator.close();assertTrue(coordinator.awaitOwnedExecutorExit(4,java.util.concurrent.TimeUnit.SECONDS));}
 }
 static final byte[] SCOPE="RB-DOWNLOADS-001".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
 static DownloadStore.Snapshot empty(long revision){return new DownloadStore.Snapshot(revision,Collections.emptyList());}
 static void seed(BrowserMetadataStoreTest.F f,DownloadStore s)throws Exception{try(DownloadStore.ReadView v=s.read(f.permit)){s.compareAndWriteCompleteIntendedMetadata(v,empty(0),f.permit);}}
 @Test public void actualNativeTaskAndActualBulkCopyProducePersistableObservationNotPublication()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();NativeTask task=new NativeTask(f.gate)){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);seed(f,s);DownloadStore.Entry queued=s.nativeRegisteredMetadata(task.task,"file.txt","text/plain","https://example.test/file",f.permit);io.github.rebrowser.download.ResponseStreamWorker.CopiedStage copy=io.github.rebrowser.download.ResponseStreamWorker.copyOwned(new java.io.ByteArrayInputStream(new byte[]{4,5,6}),new java.io.ByteArrayOutputStream(),3,3,task.task.nativeOwner().cancellation());DownloadStore.Entry observed=s.observeNativePrivateCopyReturn(queued,task.task,copy,f.permit);try(DownloadStore.ReadView v=s.read(f.permit)){s.compareAndWriteCompleteIntendedMetadata(v,v.unverifiedMetadata(f.permit).upsertNativeObservation(observed),f.permit);}try(DownloadStore.ReadView v=s.read(f.permit)){DownloadStore.Entry row=v.unverifiedMetadata(f.permit).entries().get(0);assertEquals(3,row.recordedCopiedBytes());assertEquals(DownloadStore.CopyObservation.PRIVATE_COPY_CALL_RETURNED,row.recordedCopyObservation());assertEquals(64,row.recordedOriginalSha256().length());}assertFalse(task.task.nativeOwner().hasReportedActualDomainEnd());}}
 @Test public void foreignTaskSourceCannotBeLaunderedIntoLocalEncryptedCatalog()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();BrowserMetadataStoreTest.F other=new BrowserMetadataStoreTest.F();NativeTask task=new NativeTask(other.gate)){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);assertThrows(SecurityException.class,()->s.nativeRegisteredMetadata(task.task,"file.txt","text/plain","https://example.test/file",f.permit));}}
 @Test public void nativeDownloadMetadataRejectsUnsafeSourceAndFilename()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();NativeTask task=new NativeTask(f.gate)){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);assertThrows(IllegalArgumentException.class,()->s.nativeRegisteredMetadata(task.task,"../file","text/plain","https://example.test/file",f.permit));assertThrows(IllegalArgumentException.class,()->s.nativeRegisteredMetadata(task.task,"file","text/plain","https://secret@example.test/file",f.permit));assertThrows(IllegalArgumentException.class,()->s.nativeRegisteredMetadata(task.task,"file","evil<script>","https://example.test/file",f.permit));}}
 @Test public void missingIsNotDefaultRosterOrFreshPermission()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);try(DownloadStore.ReadView v=s.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,v.kind());assertThrows(IllegalStateException.class,()->v.unverifiedMetadata(f.permit));}assertFalse(Files.exists(f.root.resolve(f.records.reference(PrivateRecordSealer.Purpose.DOWNLOADS,SCOPE,f.permit).opaqueRef())));}}
 @Test public void explicitSyntheticWholeSnapshotRoundTripsP6()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);seed(f,s);try(DownloadStore.ReadView v=s.read(f.permit)){assertEquals(PrivateRecordStore.Kind.CURRENT,v.kind());assertEquals(0,v.unverifiedMetadata(f.permit).metadataRevision());s.compareAndWriteCompleteIntendedMetadata(v,empty(1),f.permit);}try(DownloadStore.ReadView v=s.read(f.permit)){assertEquals(1,v.unverifiedMetadata(f.permit).metadataRevision());}}}
 @Test public void actualCurrentDiskStampProtectsConcurrentReplacement()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);seed(f,s);try(DownloadStore.ReadView old=s.read(f.permit);PrivateRecordStore.ReadRecord raw=f.records.read(f.records.reference(PrivateRecordSealer.Purpose.DOWNLOADS,SCOPE,f.permit),f.permit)){f.records.write(raw.stamp(),DownloadStore.CODEC.encode(empty(1)),f.permit);assertThrows(java.io.IOException.class,()->s.compareAndWriteCompleteIntendedMetadata(old,empty(1),f.permit));}}}
 @Test public void oneAttemptEvenAfterSuccessOrBadRevision()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);seed(f,s);try(DownloadStore.ReadView v=s.read(f.permit)){assertThrows(IllegalArgumentException.class,()->s.compareAndWriteCompleteIntendedMetadata(v,empty(0),f.permit));assertThrows(IllegalArgumentException.class,()->s.compareAndWriteCompleteIntendedMetadata(v,empty(1),f.permit));}}}
 @Test public void decodedCreditHeldUntilActualViewClose()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);DownloadStore.ReadView v=s.read(f.permit);assertThrows(IllegalStateException.class,()->s.read(f.permit));v.close();try(DownloadStore.ReadView next=s.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,next.kind());}}}
 @Test public void movedPurposeCipherCannotBecomeDownloadMetadata()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){f.seedSettings(true);Path settings=f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef()),downloads=f.root.resolve(f.records.reference(PrivateRecordSealer.Purpose.DOWNLOADS,SCOPE,f.permit).opaqueRef());Files.copy(settings,downloads);DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);assertThrows(java.security.GeneralSecurityException.class,()->s.read(f.permit));}}
 @Test public void closedAndForeignReadViewsCannotWrite()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();BrowserMetadataStoreTest.F g=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit),other=DownloadStore.openExisting(g.records,g.gate,g.permit);DownloadStore.ReadView v=s.read(f.permit);assertThrows(IllegalArgumentException.class,()->other.compareAndWriteCompleteIntendedMetadata(v,empty(0),g.permit));v.close();assertThrows(IllegalStateException.class,()->s.compareAndWriteCompleteIntendedMetadata(v,empty(0),f.permit));}}
 @Test public void sameEpochNewNativeSourceCannotRetargetOldStore()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));assertThrows(SecurityException.class,()->s.read(f.gate.requireBusiness()));}}
 @Test public void nativeCodecRejectsTruncationTailAndExcessCount(){byte[] raw=DownloadStore.CODEC.encode(empty(0));for(int i=0;i<raw.length;i++){byte[] cut=Arrays.copyOf(raw,i);assertThrows(IllegalArgumentException.class,()->DownloadStore.CODEC.decode(ByteBuffer.wrap(cut)));}assertThrows(IllegalArgumentException.class,()->DownloadStore.CODEC.decode(ByteBuffer.wrap(Arrays.copyOf(raw,raw.length+1))));byte[] count=raw.clone();count[18]=1;count[19]=1;assertThrows(IllegalArgumentException.class,()->DownloadStore.CODEC.decode(ByteBuffer.wrap(count)));}
 @Test public void unfinishedWriteNeverSeededOrRemoved()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){String ref=f.records.reference(PrivateRecordSealer.Purpose.DOWNLOADS,SCOPE,f.permit).opaqueRef();Path pending=f.root.resolve(ref+".pending");Files.write(pending,new byte[]{7});DownloadStore s=DownloadStore.openExisting(f.records,f.gate,f.permit);try(DownloadStore.ReadView v=s.read(f.permit)){assertEquals(PrivateRecordStore.Kind.UNFINISHED_WRITE,v.kind());assertThrows(IllegalArgumentException.class,()->s.compareAndWriteCompleteIntendedMetadata(v,empty(0),f.permit));}assertArrayEquals(new byte[]{7},Files.readAllBytes(pending));}}
}
